CREATE TABLE IF NOT EXISTS production_certification_baseline (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), baseline_key text NOT NULL UNIQUE, organization_id uuid REFERENCES gis_organizations(id) ON DELETE CASCADE, status text NOT NULL DEFAULT 'PROVISIONED', position_count integer NOT NULL DEFAULT 0, dashboard_count integer NOT NULL DEFAULT 0, gis_dataset_status text NOT NULL DEFAULT 'NOT_LOADED', e2e_status text NOT NULL DEFAULT 'NOT_RUN', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
