INSERT INTO gis_organizations (name,slug,organization_type,status,dashboard_mode,created_by) SELECT 'ÒsánVault Africa Ltd','osanvault-africa-production','ENTERPRISE','ACTIVE','COMPANY','production-certification' WHERE NOT EXISTS (SELECT 1 FROM gis_organizations WHERE slug='osanvault-africa-production');
INSERT INTO gis_organization_positions (organization_id,position_code,position_name,dashboard_key) SELECT id,'CEO','Chief Executive Officer','executive-command' FROM gis_organizations WHERE slug='osanvault-africa-production' AND NOT EXISTS (SELECT 1 FROM gis_organization_positions p WHERE p.organization_id=gis_organizations.id AND p.position_code='CEO');
INSERT INTO gis_organization_positions (organization_id,position_code,position_name,dashboard_key) SELECT id,'COO','Chief Operating Officer','operations-command' FROM gis_organizations WHERE slug='osanvault-africa-production' AND NOT EXISTS (SELECT 1 FROM gis_organization_positions p WHERE p.organization_id=gis_organizations.id AND p.position_code='COO');
INSERT INTO gis_organization_positions (organization_id,position_code,position_name,dashboard_key) SELECT id,'CFO','Chief Financial Officer','finance-command' FROM gis_organizations WHERE slug='osanvault-africa-production' AND NOT EXISTS (SELECT 1 FROM gis_organization_positions p WHERE p.organization_id=gis_organizations.id AND p.position_code='CFO');
INSERT INTO gis_organization_positions (organization_id,position_code,position_name,dashboard_key) SELECT id,'CTO','Chief Technology Officer','technology-command' FROM gis_organizations WHERE slug='osanvault-africa-production' AND NOT EXISTS (SELECT 1 FROM gis_organization_positions p WHERE p.organization_id=gis_organizations.id AND p.position_code='CTO');
INSERT INTO gis_organization_positions (organization_id,position_code,position_name,dashboard_key) SELECT id,'CIO','Chief Investment Officer','investment-command' FROM gis_organizations WHERE slug='osanvault-africa-production' AND NOT EXISTS (SELECT 1 FROM gis_organization_positions p WHERE p.organization_id=gis_organizations.id AND p.position_code='CIO');
INSERT INTO gis_organization_positions (organization_id,position_code,position_name,dashboard_key) SELECT id,'CCO','Chief Compliance Officer','compliance-command' FROM gis_organizations WHERE slug='osanvault-africa-production' AND NOT EXISTS (SELECT 1 FROM gis_organization_positions p WHERE p.organization_id=gis_organizations.id AND p.position_code='CCO');
INSERT INTO gis_organization_dashboards (organization_id,dashboard_key,position_code,config) SELECT o.id,p.dashboard_key,p.position_code,jsonb_build_object('mode','production','position',p.position_name,'tenant','osanvault-africa-production') FROM gis_organizations o JOIN gis_organization_positions p ON p.organization_id=o.id WHERE o.slug='osanvault-africa-production' ON CONFLICT (organization_id,dashboard_key,position_code) DO UPDATE SET config=EXCLUDED.config,updated_at=now();
INSERT INTO production_certification_baseline (baseline_key,organization_id,position_count,dashboard_count) SELECT 'osanvault-africa-production',o.id,(SELECT count(*) FROM gis_organization_positions p WHERE p.organization_id=o.id),(SELECT count(*) FROM gis_organization_dashboards d WHERE d.organization_id=o.id) FROM gis_organizations o WHERE o.slug='osanvault-africa-production' ON CONFLICT (baseline_key) DO UPDATE SET organization_id=EXCLUDED.organization_id,position_count=EXCLUDED.position_count,dashboard_count=EXCLUDED.dashboard_count,status='PROVISIONED',updated_at=now();